using Assets.CoreCollapse.Scripts.Structural;using UnityEngine;using LWS.TruckTeaParty;
namespace LWS.TruckDentist {
 [RequireComponent(typeof(Rigidbody),typeof(ServingSupport))]public sealed class DentalTooth:Collapser {
  public DentistMatch match;public int id;public Rigidbody body;public Transform crown,plaque,cavity,filling;public Collider[] physical;public Rigidbody[] shards;public Vector3 spawn;public DentalTool LastExtractor,LastContactTool;public bool Extracted{get;private set;}public bool Broken{get;private set;}public float Health=>Mathf.Max(0,currentHp);public ConfigurableJoint Socket{get;private set;}Vector3[] shardPositions;Quaternion[] shardRotations;float nextDamage,nativeBreakForce=-1;
  public void Prepare(){if(LastExtractor!=null)LastExtractor.Release();LastExtractor=LastContactTool=null;nativeBreakForce=-1;support=GetComponent<Support>();support.ClearSupports();if(Socket!=null)Destroy(Socket);startingHp=currentHp=100;Extracted=Broken=false;nextDamage=0;body.isKinematic=false;body.linearVelocity=body.angularVelocity=Vector3.zero;body.position=spawn;body.rotation=Quaternion.identity;transform.SetPositionAndRotation(body.position,body.rotation);if(shardPositions==null){shardPositions=new Vector3[shards.Length];shardRotations=new Quaternion[shards.Length];for(int i=0;i<shards.Length;i++){shardPositions[i]=shards[i].transform.localPosition;shardRotations[i]=shards[i].transform.localRotation;}}foreach(var s in shards){if(!s.isKinematic)s.linearVelocity=s.angularVelocity=Vector3.zero;s.isKinematic=true;s.gameObject.SetActive(false);}crown.gameObject.SetActive(true);foreach(var c in physical)c.enabled=true;Socket=gameObject.AddComponent<ConfigurableJoint>();Socket.autoConfigureConnectedAnchor=false;Socket.anchor=Vector3.zero;Socket.connectedAnchor=spawn;Socket.xMotion=Socket.yMotion=Socket.zMotion=ConfigurableJointMotion.Locked;Socket.angularXMotion=Socket.angularYMotion=Socket.angularZMotion=ConfigurableJointMotion.Locked;Socket.breakForce=DentalRules.Task(id)==DentalTask.Loose?3500:12000;Socket.breakTorque=float.PositiveInfinity;Tick();}
  void OnCollisionEnter(Collision c)=>Contact(c);void OnCollisionStay(Collision c)=>Contact(c);void Contact(Collision c){var tool=c.collider.GetComponentInParent<DentalTool>();if(tool!=null)tool.NativeContact(this,c);}
  void OnJointBreak(float force){nativeBreakForce=force;}
  public void Mistreatment(){if(Broken||Extracted||match.rules.Clock<nextDamage)return;nextDamage=match.rules.Clock+1;ReceiveDamage(20);}
  public override void ReceiveDamage(float damage){if(Broken||Extracted||!match.Live||!float.IsFinite(damage)||damage<=0)return;base.ReceiveDamage(damage);}
  protected override void Collapse(){if(Broken)return;Broken=true;base.Collapse();if(Socket!=null)Destroy(Socket);if(LastExtractor!=null)LastExtractor.Release();crown.gameObject.SetActive(false);foreach(var c in physical)c.enabled=false;for(int i=0;i<shards.Length;i++){var s=shards[i];s.gameObject.SetActive(true);s.position=transform.TransformPoint(shardPositions[i]);s.rotation=transform.rotation*shardRotations[i];s.isKinematic=false;s.linearVelocity=body.linearVelocity+Vector3.up*1.2f+new Vector3(i%3-1,0,(i+1)%3-1);s.angularVelocity=Vector3.one*.8f;}body.isKinematic=true;match.rules.Broken(match.rules.Round,id);match.patient.React(false);}
  public void Tick(){if(match.Live&&nativeBreakForce>=0&&Socket==null&&!Broken&&!Extracted){var tool=LastExtractor!=null?LastExtractor:LastContactTool;if(tool!=null){Extracted=true;match.NativeExtraction(this,tool);}}int stage=match.rules.stage[id];plaque.gameObject.SetActive(!Broken&&DentalRules.Task(id)==DentalTask.Dirty&&stage<2);cavity.gameObject.SetActive(!Broken&&DentalRules.Task(id)==DentalTask.Cavity&&stage<4);filling.gameObject.SetActive(!Broken&&DentalRules.Task(id)==DentalTask.Cavity&&stage>=4);}
  public void Freeze(){if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;body.isKinematic=true;foreach(var s in shards){if(!s.isKinematic)s.linearVelocity=s.angularVelocity=Vector3.zero;s.isKinematic=true;}}
 }
}
